#include <iostream>
#include <vector>
using namespace std;
int main(){
    ios::sync_with_stdio(false);cin.tie(nullptr);
    int n,q;if(!(cin>>n>>q))return 0;
    vector<int> along_x(n*n,0),along_y(n*n,0),along_z(n*n,0);
    int answer=0;
    while(q--){
        int x,y,z;cin>>x>>y>>z;
        if(++along_x[y*n+z]==n)++answer;
        if(++along_y[x*n+z]==n)++answer;
        if(++along_z[x*n+y]==n)++answer;
        cout<<answer<<'\n';
    }
}
