#include <iostream>
#include <string>
#include <array>
#include <vector>
#include <algorithm>
using namespace std;
int main(){
    ios::sync_with_stdio(false);cin.tie(nullptr);
    int n,f;if(!(cin>>n>>f))return 0;string s;cin>>s;
    array<int,676> counts{};array<bool,676> good{};
    auto pattern=[&](int start){
        return s[start]!=s[start+1]&&s[start+1]==s[start+2]
            ?(s[start]-'a')*26+s[start+1]-'a':-1;
    };
    for(int start=0;start+2<n;++start){int key=pattern(start);if(key>=0)++counts[key];}
    for(int key=0;key<676;++key)good[key]=counts[key]>=f;
    for(int pos=0;pos<n;++pos){
        int left=max(0,pos-2),right=min(pos,n-3);char old=s[pos];
        vector<int> old_keys;
        for(int start=left;start<=right;++start){
            int key=pattern(start);old_keys.push_back(key);if(key>=0)--counts[key];
        }
        for(char c='a';c<='z';++c){
            s[pos]=c;vector<int> new_keys;
            for(int start=left;start<=right;++start){
                int key=pattern(start);new_keys.push_back(key);if(key>=0)++counts[key];
            }
            for(int key:new_keys)if(key>=0&&counts[key]>=f)good[key]=true;
            for(int key:new_keys)if(key>=0)--counts[key];
        }
        s[pos]=old;
        for(int key:old_keys)if(key>=0)++counts[key];
    }
    vector<string> result;
    for(int a=0;a<26;++a)for(int b=0;b<26;++b)if(a!=b&&good[a*26+b]){
        string moo;moo+=char('a'+a);moo+=char('a'+b);moo+=char('a'+b);result.push_back(moo);
    }
    cout<<result.size()<<'\n';for(const auto &moo:result)cout<<moo<<'\n';
}
